def test_no_runs(admin_client, dag_without_runs):
    resp = admin_client.get(f'/object/grid_data?dag_id={DAG_ID}', follow_redirects=True)
    assert resp.status_code == 200, resp.json
    assert resp.json == {
        'dag_runs': [],
        'groups': {
            'children': [
                {
                    'extra_links': [],
                    'id': 'task1',
                    'instances': [],
                    'is_mapped': False,
                    'label': 'task1',
                },
                {
                    'children': [
                        {
                            'extra_links': [],
                            'id': 'group.mapped',
                            'instances': [],
                            'is_mapped': True,
                            'label': 'mapped',
                        }
                    ],
                    'id': 'group',
                    'instances': [],
                    'label': 'group',
                    'tooltip': '',
                },
            ],
            'id': None,
            'instances': [],
            'label': None,
            'tooltip': '',
        },
    }

