        url = url.lstrip()

        # Don't do any URL preparation for non-HTTP schemes like `mailto`,
        # `data`, `http+unix` etc to work around exceptions from `url_parse`,
        # which handles RFC 3986 only.
        if ':' in url and not url.lower().startswith(('http://', 'https://')):
