            )

            with pytest.warns(FutureWarning):
                test_conf.validate()
                assert (
                    test_conf.get("api", "auth_backends")
                    == "airflow.providers.fab.auth_manager.api.auth.backend.basic_auth,airflow.api.auth.backend.session"
                )

