def render_text(self, outfd, data):
        for task in data:
            outfd.write("*" * 72 + "\n")
            outfd.write("Pid: {0:6}\n".format(task.UniqueProcessId))
            levels = {}
            for vad in task.VadRoot.traverse():
                if vad:
                    level = levels.get(vad.Parent.obj_offset, -1) + 1
                    levels[vad.obj_offset] = level
                    outfd.write(" " * level + "{0:08x} - {1:08x}\n".format(
                                vad.Start,
                                vad.End))

function_code:
def render_text(self, outfd, data):
        for task in data:
            outfd.write("*" * 72 + "\n")
            outfd.write("Pid: {0:6}\n".format(task.UniqueProcessId))
            levels = {}
            for vad in task.VadRoot.traverse():
                if vad:
                    level = levels.get(vad.Parent.dereference().obj_offset, -1) + 1
                    levels[vad.obj_offset] = level
                    outfd.write(" " * level + "{0:08x} - {1:08x}\n".format(
                                vad.Start,
                                vad.End))

