                except IOError as e:
                    self.logger.error("%s" % e.strerror)
                    b_rs.skip(fname, e.strerror)
            sys.stdout.write("]\n")
            sys.stdout.flush()
        else:
            self.logger.info("no filename/s provided, working from stdin")
            try:
                self._execute_ast_visitor('STDIN', sys.stdin, self.b_ma, self.b_rs)
