def getFingerprint(self):
        value = ""
        wsOsFp = Format.getOs("web server", kb.headersFp)

        if wsOsFp:
            value += "%s\n" % wsOsFp

        if kb.data.banner:
            dbmsOsFp = Format.getOs("back-end DBMS", kb.bannerFp)

            if dbmsOsFp:
                value += "%s\n" % dbmsOsFp

        value += "back-end DBMS: "

        if not conf.extensiveFp:
            value += DBMS.DB2
            return value

        actVer = Format.getDbms()
        blank = " " * 15
        value += "active fingerprint: %s" % actVer

        if kb.bannerFp:
            banVer = kb.bannerFp.get("dbmsVersion")

            if banVer:
                banVer = Format.getDbms([banVer])
                value += "\n%sbanner parsing fingerprint: %s" % (blank, banVer)

        htmlErrorFp = Format.getErrorParsedDBMSes()

        if htmlErrorFp:
            value += "\n%shtml error message fingerprint: %s" % (blank, htmlErrorFp)

        return value

def calculate(self):
        common.set_plugin_members(self)

        mounts = mac_mount.mac_mount(self._config).calculate()

        seen  = {}
        paths = {}

        for mount in mounts:
            vnode = mount.mnt_vnodelist.tqh_first

            while vnode:
                if vnode.v() in seen:
                    break

                seen[vnode.v()] = 1

                # check if parent has been seen before
                parent_key = vnode.v_parent.v()

                # if not then calc full path and store in cache
                if not parent_key in paths:    
                    paths[parent_key] = vnode.v_parent.full_path()

                if paths[parent_key] == "/":
                    sep = ""
                else:
                    sep = "/"

                # figure out our full path and store it
                path = paths[parent_key] + sep + str(vnode.v_name.dereference())
                paths[vnode.v()] = path

                yield vnode, path

                vnode = vnode.v_mntvnodes.tqe_next

