            shebang = ''

        cmd_parts = [
            shebang.removeprefix('#!').strip(),
            cmd.strip(),
            arg_path,
        ]

        return f'{env_string}%s' % self.join(cps for cp in cmd_parts if cp and (cps := cp.strip()))

