def detect(get_page):
    retval = False

    for vector in WAF_ATTACK_VECTORS:
        page, _, code = get_page(get=vector)
        retval |= (code or 0) >= 400 and "This site is protected by CrawlProtect" in (page or "")
        retval |= "<title>CrawlProtect" in (page or "")
        if retval:
            break

    return retval

