patched_function_source:
def detect(get_page):
    retval = False

    for vector in WAF_ATTACK_VECTORS:
        page, headers, code = get_page(get=vector)
        retval |= code >= 400 and headers.get("Powered-By-ChinaCache") is not None

        if retval:
            break

    return retval

