def test_present():
    """
    Test to verify that the raid is present
    """
    ret = [
        {
            "changes": {},
            "comment": "Raid salt already present.",
            "name": "salt",
            "result": True,
        },
        {
            "changes": {},
            "comment": (
                "Devices are a mix of RAID constituents with multiple MD_UUIDs:"
                " ['6be5fc45:05802bba:1c2d6722:666f0e03', 'ffffffff:ffffffff:ffffffff:ffffffff']."
            ),
            "name": "salt",
            "result": False,
        },
        {
            "changes": {},
            "comment": "Raid will be created with: True",
            "name": "salt",
            "result": None,
        },
        {
            "changes": {},
            "comment": "Raid salt failed to be created.",
            "name": "salt",
            "result": False,
        },
        {
            "changes": {"uuid": "6be5fc45:05802bba:1c2d6722:666f0e03"},
            "comment": "Raid salt created.",
            "name": "salt",
            "result": True,
        },
        {
            "changes": {
                "added": ["dev1"],
                "uuid": "6be5fc45:05802bba:1c2d6722:666f0e03",
            },
            "comment": "Raid salt assembled. Added new device dev1 to salt.\n",
            "name": "salt",
            "result": True,
        },
        {
            "changes": {"added": ["dev1"]},
            "comment": "Raid salt already present. Added new device dev1 to salt.\n",
            "name": "salt",
            "result": True,
        },
        {
            "changes": {},
            "comment": "Raid salt failed to be assembled.",
            "name": "salt",
            "result": False,
        },
    ]

    mock_raid_list_exists = MagicMock(
        return_value={"salt": {"uuid": "6be5fc45:05802bba:1c2d6722:666f0e03"}}
    )
    mock_raid_list_missing = MagicMock(return_value={})

    mock_file_access_ok = MagicMock(return_value=True)

    mock_raid_examine_ok = MagicMock(
        return_value={"MD_UUID": "6be5fc45:05802bba:1c2d6722:666f0e03"}
    )
    mock_raid_examine_missing = MagicMock(return_value={})

    mock_raid_create_success = MagicMock(return_value=True)
    mock_raid_create_fail = MagicMock(return_value=False)

    mock_raid_assemble_success = MagicMock(return_value=True)
    mock_raid_assemble_fail = MagicMock(return_value=False)

    mock_raid_add_success = MagicMock(return_value=True)

    mock_raid_save_config = MagicMock(return_value=True)

    with patch.dict(
        mdadm.__salt__,
        {
            "raid.list": mock_raid_list_exists,
            "file.access": mock_file_access_ok,
            "raid.examine": mock_raid_examine_ok,
        },
    ):
        with patch.dict(mdadm.__opts__, {"test": False}):
            assert mdadm.present("salt", 5, "dev0") == ret[0]

    mock_raid_examine_mixed = MagicMock(
        side_effect=[
            {"MD_UUID": "6be5fc45:05802bba:1c2d6722:666f0e03"},
            {"MD_UUID": "ffffffff:ffffffff:ffffffff:ffffffff"},
        ]
    )
    with patch.dict(
        mdadm.__salt__,
        {
            "raid.list": mock_raid_list_missing,
            "file.access": mock_file_access_ok,
            "raid.examine": mock_raid_examine_mixed,
        },
    ):
        with patch.dict(mdadm.__opts__, {"test": False}):
            assert mdadm.present("salt", 5, ["dev0", "dev1"]) == ret[1]

    with patch.dict(
        mdadm.__salt__,
        {
            "raid.list": mock_raid_list_missing,
            "file.access": mock_file_access_ok,
            "raid.examine": mock_raid_examine_missing,
            "raid.create": mock_raid_create_success,
        },
    ):
        with patch.dict(mdadm.__opts__, {"test": True}):
            assert mdadm.present("salt", 5, "dev0") == ret[2]

    with patch.dict(
        mdadm.__salt__,
        {
            "raid.list": mock_raid_list_missing,
            "file.access": mock_file_access_ok,
            "raid.examine": mock_raid_examine_missing,
            "raid.create": mock_raid_create_fail,
        },
    ):
        with patch.dict(mdadm.__opts__, {"test": False}):
            assert mdadm.present("salt", 5, "dev0") == ret[3]

    mock_raid_list_create = MagicMock(
        side_effect=[{}, {"salt": {"uuid": "6be5fc45:05802bba:1c2d6722:666f0e03"}}]
    )
    with patch.dict(
        mdadm.__salt__,
        {
            "raid.list": mock_raid_list_create,
            "file.access": mock_file_access_ok,
            "raid.examine": mock_raid_examine_missing,
            "raid.create": mock_raid_create_success,
            "raid.save_config": mock_raid_save_config,
        },
    ):
        with patch.dict(mdadm.__opts__, {"test": False}):
            assert mdadm.present("salt", 5, "dev0") == ret[4]

    mock_raid_examine_replaced = MagicMock(
        side_effect=[{"MD_UUID": "6be5fc45:05802bba:1c2d6722:666f0e03"}, {}]
    )
    mock_raid_list_create = MagicMock(
        side_effect=[{}, {"salt": {"uuid": "6be5fc45:05802bba:1c2d6722:666f0e03"}}]
    )
    with patch.dict(
        mdadm.__salt__,
        {
            "raid.list": mock_raid_list_create,
            "file.access": mock_file_access_ok,
            "raid.examine": mock_raid_examine_replaced,
            "raid.assemble": mock_raid_assemble_success,
            "raid.add": mock_raid_add_success,
            "raid.save_config": mock_raid_save_config,
        },
    ):
        with patch.dict(mdadm.__opts__, {"test": False}):
            assert mdadm.present("salt", 5, ["dev0", "dev1"]) == ret[5]

    mock_raid_examine_replaced = MagicMock(
        side_effect=[{"MD_UUID": "6be5fc45:05802bba:1c2d6722:666f0e03"}, {}]
    )
    with patch.dict(
        mdadm.__salt__,
        {
            "raid.list": mock_raid_list_exists,
            "file.access": mock_file_access_ok,
            "raid.examine": mock_raid_examine_replaced,
            "raid.add": mock_raid_add_success,
            "raid.save_config": mock_raid_save_config,
        },
    ):
        with patch.dict(mdadm.__opts__, {"test": False}):
            assert mdadm.present("salt", 5, ["dev0", "dev1"]) == ret[6]

    mock_raid_examine_replaced = MagicMock(
        side_effect=[{"MD_UUID": "6be5fc45:05802bba:1c2d6722:666f0e03"}, {}]
    )
    with patch.dict(
        mdadm.__salt__,
        {
            "raid.list": mock_raid_list_missing,
            "file.access": mock_file_access_ok,
            "raid.examine": mock_raid_examine_replaced,
            "raid.assemble": mock_raid_assemble_fail,
        },
    ):
        with patch.dict(mdadm.__opts__, {"test": False}):
            assert mdadm.present("salt", 5, ["dev0", "dev1"]) == ret[7]

patched_function_source:
def create(vm_):
    '''
    Create a single VM from a data dict
    '''
    try:
        # Check for required profile parameters before sending any API calls.
        if vm_['profile'] and config.is_profile_configured(__opts__,
                                                           __active_provider_name__ or 'softlayer',
                                                           vm_['profile']) is False:
            return False
    except AttributeError:
        pass

    # Since using "provider: <provider-engine>" is deprecated, alias provider
    # to use driver: "driver: <provider-engine>"
    if 'provider' in vm_:
        vm_['driver'] = vm_.pop('provider')

    name = vm_['name']
    hostname = name
    domain = config.get_cloud_config_value(
        'domain', vm_, __opts__, default=None
    )
    if domain is None:
        SaltCloudSystemExit(
            'A domain name is required for the SoftLayer driver.'
        )

    if vm_.get('use_fqdn'):
        name = '.'.join([name, domain])
        vm_['name'] = name

    salt.utils.cloud.fire_event(
        'event',
        'starting create',
        'salt/cloud/{0}/creating'.format(name),
        {
            'name': name,
            'profile': vm_['profile'],
            'provider': vm_['driver'],
        },
        transport=__opts__['transport']
    )

    log.info('Creating Cloud VM {0}'.format(name))
    conn = get_conn()
    kwargs = {
        'hostname': hostname,
        'domain': domain,
        'startCpus': vm_['cpu_number'],
        'maxMemory': vm_['ram'],
        'hourlyBillingFlag': vm_['hourly_billing'],
    }

    local_disk_flag = config.get_cloud_config_value(
        'local_disk', vm_, __opts__, default=False
    )
    kwargs['localDiskFlag'] = local_disk_flag

    if 'image' in vm_:
        kwargs['operatingSystemReferenceCode'] = vm_['image']
        kwargs['blockDevices'] = []
        disks = vm_['disk_size']

        if isinstance(disks, int):
            disks = [str(disks)]
        elif isinstance(disks, str):
            disks = [size.strip() for size in disks.split(',')]

        count = 0
        for disk in disks:
            # device number '1' is reserved for the SWAP disk
            if count == 1:
                count += 1
            block_device = {'device': str(count),
                            'diskImage': {'capacity': str(disk)}}
            kwargs['blockDevices'].append(block_device)
            count += 1

            # Upper bound must be 5 as we're skipping '1' for the SWAP disk ID
            if count > 5:
                log.warning('More that 5 disks were specified for {0} .'
                            'The first 5 disks will be applied to the VM, '
                            'but the remaining disks will be ignored.\n'
                            'Please adjust your cloud configuration to only '
                            'specify a maximum of 5 disks.'.format(name))
                break

    elif 'global_identifier' in vm_:
        kwargs['blockDeviceTemplateGroup'] = {
            'globalIdentifier': vm_['global_identifier']
        }

    location = get_location(vm_)
    if location:
        kwargs['datacenter'] = {'name': location}

    private_vlan = config.get_cloud_config_value(
        'private_vlan', vm_, __opts__, default=False
    )
    if private_vlan:
        kwargs['primaryBackendNetworkComponent'] = {
            'networkVlan': {
                'id': private_vlan,
            }
        }

    private_network = config.get_cloud_config_value(
        'private_network', vm_, __opts__, default=False
    )
    if bool(private_network) is True:
        kwargs['privateNetworkOnlyFlag'] = 'True'

    public_vlan = config.get_cloud_config_value(
        'public_vlan', vm_, __opts__, default=False
    )
    if public_vlan:
        kwargs['primaryNetworkComponent'] = {
            'networkVlan': {
                'id': public_vlan,
            }
        }

    max_net_speed = config.get_cloud_config_value(
        'max_net_speed', vm_, __opts__, default=10
    )
    if max_net_speed:
        kwargs['networkComponents'] = [{
            'maxSpeed': int(max_net_speed)
        }]

    post_uri = config.get_cloud_config_value(
        'post_uri', vm_, __opts__, default=None
    )
    if post_uri:
        kwargs['postInstallScriptUri'] = post_uri

    salt.utils.cloud.fire_event(
        'event',
        'requesting instance',
        'salt/cloud/{0}/requesting'.format(name),
        {'kwargs': kwargs},
        transport=__opts__['transport']
    )

    try:
        response = conn.createObject(kwargs)
    except Exception as exc:
        log.error(
            'Error creating {0} on SoftLayer\n\n'
            'The following exception was thrown when trying to '
            'run the initial deployment: \n{1}'.format(
                name, str(exc)
            ),
            # Show the traceback if the debug logging level is enabled
            exc_info_on_loglevel=logging.DEBUG
        )
        return False

    ip_type = 'primaryIpAddress'
    private_ssh = config.get_cloud_config_value(
        'private_ssh', vm_, __opts__, default=False
    )
    private_wds = config.get_cloud_config_value(
        'private_windows', vm_, __opts__, default=False
    )
    if private_ssh or private_wds or public_vlan is None or public_vlan is False:
        ip_type = 'primaryBackendIpAddress'

    def wait_for_ip():
        '''
        Wait for the IP address to become available
        '''
        nodes = list_nodes_full()
        if ip_type in nodes[hostname]:
            return nodes[hostname][ip_type]
        time.sleep(1)
        return False

    ip_address = salt.utils.cloud.wait_for_fun(
        wait_for_ip,
        timeout=config.get_cloud_config_value(
            'wait_for_fun_timeout', vm_, __opts__, default=15 * 60),
    )
    if config.get_cloud_config_value('deploy', vm_, __opts__) is not True:
        return show_instance(hostname, call='action')

    SSH_PORT = 22
    WINDOWS_DS_PORT = 445
    managing_port = SSH_PORT
    if config.get_cloud_config_value('windows', vm_, __opts__) or \
            config.get_cloud_config_value('win_installer', vm_, __opts__):
        managing_port = WINDOWS_DS_PORT

    ssh_connect_timeout = config.get_cloud_config_value(
        'ssh_connect_timeout', vm_, __opts__, 15 * 60
    )
    connect_timeout = config.get_cloud_config_value(
        'connect_timeout', vm_, __opts__, ssh_connect_timeout
    )
    if not salt.utils.cloud.wait_for_port(ip_address,
                                          port=managing_port,
                                          timeout=connect_timeout):
        raise SaltCloudSystemExit(
            'Failed to authenticate against remote ssh'
        )

    pass_conn = get_conn(service='SoftLayer_Account')
    mask = {
        'virtualGuests': {
            'powerState': '',
            'operatingSystem': {
                'passwords': ''
            },
        },
    }

    def get_credentials():
        '''
        Wait for the password to become available
        '''
        node_info = pass_conn.getVirtualGuests(id=response['id'], mask=mask)
        for node in node_info:
            if node['id'] == response['id'] and \
                            'passwords' in node['operatingSystem'] and \
                            len(node['operatingSystem']['passwords']) > 0:
                return node['operatingSystem']['passwords'][0]['username'], node['operatingSystem']['passwords'][0]['password']
        time.sleep(5)
        return False

    username, passwd = salt.utils.cloud.wait_for_fun(  # pylint: disable=W0633
        get_credentials,
        timeout=config.get_cloud_config_value(
            'wait_for_fun_timeout', vm_, __opts__, default=15 * 60),
    )
    response['username'] = username
    response['password'] = passwd
    response['public_ip'] = ip_address

    ssh_username = config.get_cloud_config_value(
        'ssh_username', vm_, __opts__, default=username
    )

    vm_['ssh_host'] = ip_address
    vm_['password'] = passwd
    ret = salt.utils.cloud.bootstrap(vm_, __opts__)

    ret.update(response)

    salt.utils.cloud.fire_event(
        'event',
        'created instance',
        'salt/cloud/{0}/created'.format(name),
        {
            'name': name,
            'profile': vm_['profile'],
            'provider': vm_['driver'],
        },
        transport=__opts__['transport']
    )

    return ret

