def score_model(spark, data_path, model_uri):
    if os.path.isdir(data_path):
        filenames = [
            os.path.abspath(os.path.join(data_path, x))
            for x in os.listdir(data_path)
            if os.path.isfile(os.path.join(data_path, x))
        ]
    else:
        filenames = [data_path]

