def _get_table_info_distorm(self):
        """
        Find the size of the system call table by disassembling functions
        that immediately reference it in their first isntruction
        This is in the form 'cmp reg,NR_syscalls'
        """
        table_size = 0

        if not has_distorm:
            return table_size

        memory_model = self.addr_space.profile.metadata.get('memory_model', '32bit')

        if memory_model == '32bit':
            mode = distorm3.Decode32Bits
            func = "sysenter_do_call"
        else:
            mode = distorm3.Decode64Bits
            func = "system_call_fastpath"

        func_addr = self.get_profile_symbol(func)

        if func_addr:

            data = self.addr_space.read(func_addr, 6)

            for op in distorm3.Decompose(func_addr, data, mode):

                if not op.valid:
                    continue

                if op.mnemonic == 'CMP':
                    table_size = (op.operands[1].value) & 0xffffffff
                    break

        return table_size

def calculate(self):
        mac_common.set_plugin_members(self)

        tasks = mac_tasks.mac_tasks(self._config).calculate()

        for task in tasks:
            proc_as = task.get_process_address_space()

            # In cases when mm is an invalid pointer 
            if not proc_as:
                continue

            # Are we dealing with 32 or 64-bit pointers
            bit_string = str(task.task.map.pmap.pm_task_map or '')[9:]
            if bit_string.find("64BIT") == -1:
                pack_format = "<I"
                addr_sz = 4
                addr_type = "unsigned int"
            else:
                pack_format = "<Q"
                addr_sz = 8
                addr_type = "unsigned long long"

            procvars = []
            for mapping in task.get_proc_maps():
                if not str(mapping.get_perms()) == "rw-" or mapping.get_path().find("bash") == -1:
                    continue

                env_start = 0
                for off in range(mapping.links.start, mapping.links.end):
                    # check the first index
                    addrstr = proc_as.read(off, addr_sz)
                    if not addrstr or len(addrstr) != addr_sz:
                        continue
                    addr = struct.unpack(pack_format, addrstr)[0]
                    # check first idx...
                    if addr:
                        firstaddrstr = proc_as.read(addr, addr_sz)
                        if not firstaddrstr or len(firstaddrstr) != addr_sz:
                            continue
                        firstaddr = struct.unpack(pack_format, firstaddrstr)[0]
                        buf = proc_as.read(firstaddr, 64)
                        if not buf:
                            continue
                        eqidx = buf.find("=")
                        if eqidx > 0:
                            nullidx = buf.find("\x00")
                            # single char name, =
                            if nullidx >= eqidx:
                                env_start = addr

                if env_start == 0:
                    continue

                envars = obj.Object(theType="Array", targetType=addr_type, vm=proc_as, offset=env_start, count=256)
                for var in envars:
                    if var:
                        sizes = [8, 16, 32, 64, 128, 256, 384, 512, 1024, 2048, 4096]
                        good_varstr = None

                        for size in sizes:
                            varstr = proc_as.read(var, size)
                            if not varstr:
                                continue

                            eqidx = varstr.find("=")
                            idx = varstr.find("\x00")

                            if idx == -1 or eqidx == -1 or idx < eqidx:
                                continue

                            good_varstr = varstr
                            break

                        if good_varstr:        
                            good_varstr = good_varstr[:idx]
                            procvars.append(good_varstr) 

                yield task, " ".join(procvars)

                break

