def walk_sbs(self, find_file):
        ret = None
        sbs = self.get_sbs()

        first_dir = "/".join(find_file.split("/")[:2])

        for (sb, path) in sbs:

            if len(path) > 1 and not path.startswith(first_dir):
                continue

            if path != "/":
                parent = path
            else:
                parent = ""

            ret = self.walk_sb(sb.s_root, find_file, None, parent = parent)

            if ret:
                break

        return ret

