def get_all():
    # This command is deprecated, however there is no new command in launchctl
    # to list daemons
    cmd = ['launchctl', 'list']
    ret = __salt__['cmd.run'](cmd)

    services = []
    for line in ret.splitlines():
        if line.split('\t')[2] != 'Label':
            services.append = line.split('\t')[2].strip()

    return services

