def dump_hashes(sysaddr, samaddr):
    bootkey = get_bootkey(sysaddr)
    hbootkey = get_hbootkey(samaddr, bootkey)

    if hbootkey:
        for user in get_user_keys(samaddr):
            lmhash, nthash = get_user_hashes(user, hbootkey)
            if not lmhash:
                lmhash = empty_lm
            if not nthash:
                nthash = empty_nt
            yield "{0}:{1}:{2}:{3}:::".format(get_user_name(user), int(str(user.Name), 16),
                                              lmhash.encode('hex'), nthash.encode('hex'))
    else:
        yield obj.NoneObject("Hbootkey is not valid")

patched_function_source:
def is_kvm_hyper():
    '''
    Returns a bool whether or not this node is a hypervisor
    '''
    if __facter__['virtual'] != 'physical':
        return False
    if not subprocess.call('lsmod | grep kvm_', shell=True):
        return False
    if not subprocess.call('ps aux | grep libvirtd | grep -v grep', shell=True):
        return False
    return True

